package mx.siabuc.helpdesk;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.annotation.Isolation;
@Service
public class InstallmentService {
 public record Input(UUID requestId,Long policyId,LocalDate dueOn,BigDecimal amount,String description){}
 public record Link(Long paymentId,BigDecimal amount){}
 public record Reason(String reason){}
 public record Settings(Boolean enabled,Integer daysBeforeDue){}
 public record Row(long id,long policyId,long institutionId,String institutionName,String policyFolio,LocalDate dueOn,BigDecimal amount,BigDecimal allocatedAmount,BigDecimal pendingAmount,String description,String status,boolean cancelled,String createdBy,Instant createdAt){}
 public record Allocation(long id,long paymentId,String reference,BigDecimal amount,boolean paymentVoided,boolean removed,String removedReason,String createdBy,Instant createdAt){}
 public record History(long id,String action,String description,String createdBy,Instant createdAt){}
 public record Detail(Row installment,List<Allocation> allocations,List<History> history,List<Models.Payment> payments){}
 public record Notice(long id,long installmentId,String policyFolio,String institutionName,LocalDate dueOn,String kind,BigDecimal pendingAmount,boolean stillRelevant,Instant createdAt,Instant readAt){}
 public record Overview(Settings settings,List<Row> installments,List<Notice> notices){}
 public record ScanResult(int created){}
 private final JdbcTemplate db;private final HelpdeskService helpdesk;private final PolicyService policies;
 public InstallmentService(JdbcTemplate db,HelpdeskService helpdesk,PolicyService policies){this.db=db;this.helpdesk=helpdesk;this.policies=policies;}
 private static LocalDate today(){return LocalDate.now(ZoneId.of("America/Mexico_City"));}
 private static final String SELECT="""
 SELECT x.*,p.institution_id,p.folio AS policy_folio,p.status AS policy_status,i.name AS institution_name,i.active AS institution_active,u.username AS creator,
 COALESCE(a.paid,0) AS paid FROM policy_installments x JOIN support_policies p ON p.id=x.policy_id
 JOIN institutions i ON i.id=p.institution_id JOIN app_users u ON u.id=x.created_by
 LEFT JOIN (SELECT a.installment_id,SUM(a.amount) AS paid FROM installment_allocations a JOIN payments p ON p.id=a.payment_id
 WHERE NOT a.removed AND NOT p.voided GROUP BY a.installment_id) a ON a.installment_id=x.id
 """;
 private static final RowMapper<Row> ROW=(r,n)->{BigDecimal amount=r.getBigDecimal("amount"),paid=r.getBigDecimal("paid");LocalDate due=r.getDate("due_on").toLocalDate();boolean cancelled=r.getBoolean("cancelled")||r.getString("policy_status").equals("CANCELLED");String status=cancelled?"CANCELLED":!r.getBoolean("institution_active")?"INACTIVE":paid.compareTo(amount)>=0?"PAID":due.isBefore(today())?"OVERDUE":"UPCOMING";return new Row(r.getLong("id"),r.getLong("policy_id"),r.getLong("institution_id"),r.getString("institution_name"),r.getString("policy_folio"),due,amount,paid,cancelled?BigDecimal.ZERO:amount.subtract(paid),r.getString("description"),status,r.getBoolean("cancelled"),r.getString("creator"),r.getTimestamp("created_at").toInstant());};
 @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
 public Overview overview(){Models.User a=actor();return new Overview(settingsData(),db.query(SELECT+" ORDER BY x.due_on,x.id",ROW),notices(a.id()));}
 @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
 public Detail detail(long id){actor();return data(id);}
 private Row row(long id){List<Row> rows=db.query(SELECT+" WHERE x.id=?",ROW,id);if(rows.isEmpty())throw ApiException.missing();return rows.get(0);}
 private Detail data(long id){Row r=row(id);return new Detail(r,db.query("SELECT a.*,p.reference,p.voided,u.username AS creator FROM installment_allocations a JOIN payments p ON p.id=a.payment_id JOIN app_users u ON u.id=a.created_by WHERE a.installment_id=? ORDER BY a.id DESC",(v,n)->new Allocation(v.getLong("id"),v.getLong("payment_id"),v.getString("reference"),v.getBigDecimal("amount"),v.getBoolean("voided"),v.getBoolean("removed"),v.getString("removed_reason"),v.getString("creator"),v.getTimestamp("created_at").toInstant()),id),db.query("SELECT h.*,u.username AS creator FROM installment_history h JOIN app_users u ON u.id=h.created_by WHERE installment_id=? ORDER BY h.id DESC",(v,n)->new History(v.getLong("id"),v.getString("action"),v.getString("description"),v.getString("creator"),v.getTimestamp("created_at").toInstant()),id),db.query(HelpdeskService.PAYMENT_SELECT+" WHERE p.policy_id=? ORDER BY p.id DESC",HelpdeskService.PAYMENT,r.policyId()));}
 @Transactional public Detail create(Input i){Models.User a=actor();if(i==null||i.requestId()==null||i.policyId()==null||i.policyId()<=0)throw ApiException.bad("Indique identificador de solicitud y póliza.");if(i.dueOn()==null||i.dueOn().getYear()<1||i.dueOn().getYear()>9999)throw ApiException.bad("Indique una fecha de vencimiento válida.");SupportPackageService.amount(i.amount());SupportPackageService.text(i.description(),"Descripción",1000);PolicyService.Policy p=lockPolicy(i.policyId());List<Long> replay=db.query("SELECT id FROM policy_installments WHERE request_id=?",(r,n)->r.getLong(1),i.requestId());if(!replay.isEmpty()){Row r=row(replay.get(0));if(r.policyId()!=i.policyId()||!r.dueOn().equals(i.dueOn())||r.amount().compareTo(i.amount())!=0||!r.description().equals(i.description().strip()))throw ApiException.conflict("La solicitud ya se utilizó con otros datos.");return data(r.id());}
 active(p);BigDecimal planned=db.queryForObject("SELECT COALESCE(SUM(amount),0) FROM policy_installments WHERE policy_id=? AND NOT cancelled",BigDecimal.class,p.id());if(planned.add(i.amount()).compareTo(p.agreedAmount())>0)throw ApiException.conflict("Las parcialidades no pueden superar el importe contratado de la póliza.");long id=db.queryForObject("INSERT INTO policy_installments(policy_id,request_id,due_on,amount,description,created_by) VALUES(?,?,?,?,?,?) RETURNING id",Long.class,p.id(),i.requestId(),java.sql.Date.valueOf(i.dueOn()),i.amount(),i.description().strip(),a.id());event(id,"CREATE_INSTALLMENT",a,"Compromiso por $"+i.amount()+" MXN para "+i.dueOn()+". "+i.description().strip()+". No registra pagos ni acredita minutos.");return data(id);}
 @Transactional public Detail cancel(long id,Reason reason){Models.User a=actor();reason(reason);Row r=lock(id);if(r.cancelled())return data(id);long linked=db.queryForObject("SELECT COUNT(*) FROM installment_allocations WHERE installment_id=? AND NOT removed",Long.class,id);if(linked>0)throw ApiException.conflict("Retire primero las aplicaciones de pago, incluidas las anuladas, conservando su historial.");db.update("UPDATE policy_installments SET cancelled=TRUE,cancel_reason=?,cancelled_at=NOW() WHERE id=?",reason.reason().strip(),id);event(id,"CANCEL_INSTALLMENT",a,reason.reason().strip());return data(id);}
 @Transactional public Detail allocate(long id,Link link){Models.User a=actor();if(link==null||link.paymentId()==null||link.paymentId()<=0)throw ApiException.bad("Seleccione un pago existente.");SupportPackageService.amount(link.amount());Row r=lock(id);if(r.status().equals("CANCELLED")||r.status().equals("INACTIVE"))throw ApiException.conflict("La parcialidad, póliza o institución no está activa.");List<Models.Payment> payments=db.query(HelpdeskService.PAYMENT_SELECT+" WHERE p.id=?",HelpdeskService.PAYMENT,link.paymentId());if(payments.isEmpty())throw ApiException.missing();Models.Payment payment=payments.get(0);if(payment.policyId()==null||payment.policyId()!=r.policyId()||payment.institutionId()!=r.institutionId()||payment.voided()||!payment.currency().equals("MXN"))throw ApiException.conflict("El pago debe estar vigente y pertenecer a la misma póliza e institución, en MXN.");List<BigDecimal> previous=db.query("SELECT amount FROM installment_allocations WHERE installment_id=? AND payment_id=? AND NOT removed",(v,n)->v.getBigDecimal(1),id,link.paymentId());if(!previous.isEmpty()){if(previous.get(0).compareTo(link.amount())!=0)throw ApiException.conflict("Este pago ya tiene otro importe aplicado. Retire esa aplicación antes de corregirla.");return data(id);}
 BigDecimal used=db.queryForObject("SELECT COALESCE(SUM(amount),0) FROM installment_allocations WHERE payment_id=? AND NOT removed",BigDecimal.class,link.paymentId());if(used.add(link.amount()).compareTo(payment.amount())>0)throw ApiException.conflict("La suma aplicada supera el importe disponible del pago.");if(r.allocatedAmount().add(link.amount()).compareTo(r.amount())>0)throw ApiException.conflict("La aplicación supera el importe pendiente de la parcialidad.");db.update("INSERT INTO installment_allocations(installment_id,payment_id,amount,created_by) VALUES(?,?,?,?)",id,link.paymentId(),link.amount(),a.id());event(id,"ALLOCATE_PAYMENT",a,"Aplicado pago #"+payment.id()+" "+payment.reference()+" por $"+link.amount()+" MXN. No acredita minutos adicionales.");return data(id);}
 @Transactional public Detail remove(long id,long allocation,Reason reason){Models.User a=actor();reason(reason);lock(id);List<Boolean> rows=db.query("SELECT removed FROM installment_allocations WHERE id=? AND installment_id=?",(r,n)->r.getBoolean(1),allocation,id);if(rows.isEmpty())throw ApiException.missing();if(!rows.get(0)){db.update("UPDATE installment_allocations SET removed=TRUE,removed_reason=?,removed_by=?,removed_at=NOW() WHERE id=?",reason.reason().strip(),a.id(),allocation);event(id,"REMOVE_ALLOCATION",a,"Aplicación #"+allocation+" retirada. "+reason.reason().strip());}return data(id);}
 private PolicyService.Policy lockPolicy(long id){PolicyService.Policy p=policies.policy(id);db.queryForObject("SELECT id FROM institutions WHERE id=? FOR UPDATE",Long.class,p.institutionId());policies.lockForAccounting(id,p.institutionId());return policies.policy(id);}
 private Row lock(long id){Row r=row(id);lockPolicy(r.policyId());db.queryForObject("SELECT id FROM policy_installments WHERE id=? FOR UPDATE",Long.class,id);return row(id);}
 private void active(PolicyService.Policy p){if(!p.status().equals("ACTIVE")||!Boolean.TRUE.equals(db.queryForObject("SELECT active FROM institutions WHERE id=?",Boolean.class,p.institutionId())))throw ApiException.conflict("La póliza o institución no está activa.");}
 private Settings settingsData(){return db.queryForObject("SELECT enabled,days_before_due FROM installment_settings WHERE id=1",(r,n)->new Settings(r.getBoolean(1),r.getInt(2)));}
 @Transactional public Settings settings(Settings s){Models.User a=actor();if(s==null||s.enabled()==null||s.daysBeforeDue()==null||s.daysBeforeDue()<0||s.daysBeforeDue()>365)throw ApiException.bad("Anticipación entera de 0 a 365 días.");db.queryForObject("SELECT id FROM installment_settings WHERE id=1 FOR UPDATE",Integer.class);db.update("UPDATE installment_settings SET enabled=?,days_before_due=? WHERE id=1",s.enabled(),s.daysBeforeDue());db.update("INSERT INTO audit_log(actor,action,entity_type,entity_id,details) VALUES(?,'INSTALLMENT_SETTINGS','INSTALLMENT_SETTINGS',1,?)",a.username(),s.toString());return settingsData();}
 @Transactional public ScanResult scan(){actor();return scanDue();}
 @Transactional public ScanResult scanDue(){db.queryForObject("SELECT id FROM installment_settings WHERE id=1 FOR UPDATE",Integer.class);Settings s=settingsData();if(!s.enabled())return new ScanResult(0);int created=0;for(Row r:db.query(SELECT+" WHERE NOT x.cancelled AND p.status='ACTIVE' AND i.active AND x.due_on<=? ORDER BY x.id",ROW,java.sql.Date.valueOf(today().plusDays(s.daysBeforeDue())))){if(r.pendingAmount().signum()<=0)continue;String kind=r.dueOn().isBefore(today())?"OVERDUE":"UPCOMING";created+=db.update("INSERT INTO installment_notices(installment_id,kind,due_on) VALUES(?,?,?) ON CONFLICT(installment_id,kind,due_on) DO NOTHING",r.id(),kind,java.sql.Date.valueOf(r.dueOn()));}return new ScanResult(created);}
 @Transactional public void read(long id){Models.User a=actor();if(db.queryForObject("SELECT COUNT(*) FROM installment_notices WHERE id=?",Long.class,id)==0)throw ApiException.missing();db.update("INSERT INTO installment_notice_reads(notice_id,user_id) VALUES(?,?) ON CONFLICT(notice_id,user_id) DO NOTHING",id,a.id());}
 private List<Notice> notices(long user){return db.query("SELECT n.*,v.read_at FROM installment_notices n LEFT JOIN installment_notice_reads v ON v.notice_id=n.id AND v.user_id=? ORDER BY n.id DESC LIMIT 200",(r,n)->{Row x=row(r.getLong("installment_id"));String kind=r.getString("kind");boolean relevant=x.pendingAmount().signum()>0&&!x.status().equals("CANCELLED")&&!x.status().equals("INACTIVE")&&(kind.equals("OVERDUE")?x.dueOn().isBefore(today()):!x.dueOn().isBefore(today()));return new Notice(r.getLong("id"),x.id(),x.policyFolio(),x.institutionName(),r.getDate("due_on").toLocalDate(),kind,x.pendingAmount(),relevant,r.getTimestamp("created_at").toInstant(),r.getTimestamp("read_at")==null?null:r.getTimestamp("read_at").toInstant());},user);}
 private void event(long id,String action,Models.User a,String text){db.update("INSERT INTO installment_history(installment_id,action,description,created_by) VALUES(?,?,?,?)",id,action,text,a.id());db.update("INSERT INTO audit_log(actor,action,entity_type,entity_id,details) VALUES(?,?,'INSTALLMENT',?,?)",a.username(),action,id,text);}
 private Models.User actor(){Models.User a=helpdesk.me();if(a.role()!=Models.Role.ADMIN&&a.role()!=Models.Role.BILLING)throw ApiException.forbidden();return a;}
 private static void reason(Reason r){SupportPackageService.text(r==null?null:r.reason(),"Motivo",2000);}
}
